/// Finds the maximum value in a vector of integers.
///
/// This function takes a slice of i32 integers and returns an Option<i32>
/// containing the maximum value if the vector is not empty. If the vector is
/// empty, it returns None.
///
/// # Arguments
///
/// * `numbers`: A slice of i32 integers.
///
/// # Returns
///
/// * `Some(i32)`: The maximum value in the vector.
/// * `None`: If the vector is empty.
///
/// # Example
///
/// ```
/// let numbers = vec![1, 5, 2, 8, 3];
/// let max_value = find_max(&numbers);
/// assert_eq!(max_value, Some(8));
///
/// let empty_vector: Vec<i32> = Vec::new();
/// let max_value = find_max(&empty_vector);
/// assert_eq!(max_value, None);
/// ```
pub fn find_max(numbers: &[i32]) -> Option<i32> {
    if numbers.is_empty() {
        return None;
    }

    let mut max_value = numbers[0];
    for &number in numbers {
        if number > max_value {
            max_value = number;
        }
    }

    Some(max_value)
}

