// UserList Component
function UserList({ users, isLoading, error }: { users: User[]; isLoading: boolean; error: string | null }) {
  const [searchTerm, setSearchTerm] = useState('');

  useEffect(() => {
    // Update search term whenever it changes
    setSearchTerm(searchTerm);
  }, [searchTerm]);

  const filteredUsers = users.filter(user =>
    user.name.toLowerCase().includes(searchTerm.toLowerCase())
  );

  if (isLoading) {
    return <p>Loading users...</p>;
  }

  if (error) {
    return <p>Error: {error}</p>;
  }

  if (!users || users.length === 0) {
    return <p>No users found.</p>;
  }

  return (
    <div aria-label="User List" role="list" className="user-list">
      <h2>User List</h2>
      <input
        type="text"
        placeholder="Search by name..."
        value={searchTerm}
        onChange={e => setSearchTerm(e.target.value)}
        aria-label="Search for users"
        autoFocus // Add autoFocus for better UX
      />
      {filteredUsers.map(user => (
        <div key={user.id} className="user-item">
          <div className="user-name">{user.name}</div>
          <div className="user-email">{user.email}</div>
        </div>
      ))}
    </div>
  );
}

export default UserList;
